// Firm names in the corrections sheet do not match INVESTORS exactly.
// Only an exact normalised match or an explicit alias is accepted - never a fuzzy guess,
// because writing an email onto the wrong investor row sends real mail to the wrong firm.
const ALIAS = {
  'mventures': 'M Venture Partners',
  'firesideventures': 'Fireside Ventures',
  'debtworks': 'Debtworks DEBT',
  'capitala': 'Capital-A',
  'flipkart': 'Flipkart Ventures',
  'blincinvest': 'Blinc Invest',
  'tvscapitalfunds': 'TVS Capital Funds',
  'piperserica': 'PiperSireca',
  'ricebergvc': 'Riceberg Ventures',
  'cedarhillcapital': 'CedarHill Capital',
  'rainmatterzerodha': 'Rainmatter by Zerodha',
  'swishinvc': 'Swishin Ventures',
  '247vc': '247 VC Tech Fund',
  'sianacapital': 'Siana Capital',
  'zerencapital': 'Zeren Capital',
  'vertex': 'Vertex Ventures',
  'caspian': 'BlackSoil Capital (formerly Caspian Debt)',
  'blacksoil': 'BlackSoil Capital (formerly Caspian Debt)'
};
function s(v) { return String(v == null ? '' : v).trim(); }
function norm(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const corr = $('Read Mail correction').all().map(function (i) { return i.json; });
const inv = $input.all().map(function (i) { return i.json; });
if (inv.length < 100) { throw new Error('ABORT: INVESTORS returned only ' + inv.length + ' rows'); }

const byNorm = {};
for (const r of inv) { byNorm[norm(r.investor)] = r; }

const out = [], unmatched = [], skipped = [];
for (const c of corr) {
  const firm = s(c['Firm name']);
  const want = s(c['Correct Mails']).replace(/\s*;\s*/g, ',').replace(/\s*,\s*/g, ',');
  const who  = s(c['updated contact name']);
  if (!firm) { continue; }

  const key = norm(firm);
  const target = byNorm[key] || (ALIAS[key] ? byNorm[norm(ALIAS[key])] : null);

  // 'Not available' means no working address exists for this firm -> stop contacting them.
  // do_not_contact is checked in 'Decide ONE action per row' BEFORE the follow-up branch,
  // so this halts new sends and any remaining follow-ups in one field.
  if (!want || want.toLowerCase() === 'not available') {
    if (!target) { skipped.push(firm + ' (not in INVESTORS)'); continue; }
    // user override 11 Sep 2026: keep contacting these even though the sheet says 'Not available'
    if (['climateangels'].indexOf(norm(target.investor)) >= 0) { skipped.push(firm + ' (user override: keep contacting)'); continue; }
    if (s(target.do_not_contact).toLowerCase() === 'yes') { continue; }
    out.push({ json: { investor: s(target.investor), do_not_contact: 'Yes' } });
    continue;
  }

  if (!target) { unmatched.push(firm); continue; }
  if (s(target.do_not_contact).toLowerCase() === 'yes') { skipped.push(firm + ' (do_not_contact)'); continue; }

  const cur = s(target.email).replace(/\s*,\s*/g, ',');
  const row = { investor: s(target.investor) };
  let changed = 0;
  if (cur.toLowerCase() !== want.toLowerCase()) { row.email = want; changed++; }
  if (who && who.toLowerCase() !== 'not available' && s(target.contact_person) !== who) { row.contact_person = who; changed++; }
  if (changed > 0) { out.push({ json: row }); }
}

// A firm that has a real corrected email but no INVESTORS match must NOT be skipped quietly -
// that is the silent-failure mode this system keeps hitting. Fail loudly so the alias map gets fixed.
if (unmatched.length > 0) { throw new Error('ABORT: corrections sheet lists firms not found in INVESTORS: ' + unmatched.join(', ') + ' - add an alias and re-run'); }
if (out.length > 25) { throw new Error('ABORT: ' + out.length + ' updates exceeds guard of 25'); }
if (out.length === 0) { return []; }   // nothing to do today - not an error
return out;

